INSERT INTO exercises
(exercise_id,concept_id,exercise_order,exercise_type,prompt,prompt_pinyin,instruction,answer,options,accepted_answers,explanation,target_tokens,error_tags,difficulty,points,metadata)
VALUES
('hsk1_c01_e01','hsk1_c01',1,'meaning_mcq','你好',NULL,'Choose the meaning.','{"value":"Hello"}','["Hello","Thank you","Goodbye","Sorry"]','[]','你好 means “hello”.','["你好"]','["vocab_meaning"]',1,10,'{}'),
('hsk1_c01_e02','hsk1_c01',2,'en_to_zh_mcq','Goodbye',NULL,'Choose the Chinese expression.','{"value":"再见"}','["你好","谢谢","再见","不客气"]','[]','再见 is the standard beginner expression for goodbye.','["再见"]','["vocab_recall"]',1,10,'{}'),
('hsk1_c01_e03','hsk1_c01',3,'fill_blank','A: 你好！ B: ____！',NULL,'Complete the dialogue.','{"value":"你好"}',NULL,'["你好"]','Return the greeting with 你好.','["你好"]','["dialogue"]',1,10,'{}'),
('hsk1_c01_e04','hsk1_c01',4,'dialogue_choice','A: 谢谢！ B: ____',NULL,'Choose the best reply.','{"value":"不客气"}','["不客气","再见","你好","对不起"]','[]','不客气 is a common reply to 谢谢.','["不客气"]','["dialogue"]',1,10,'{}'),
('hsk1_c02_e01','hsk1_c02',1,'fill_blank','我____安娜。',NULL,'Complete: “My name is Anna.”','{"value":"叫"}',NULL,'["叫"]','Use 叫 before your name.','["叫"]','["self_intro"]',1,10,'{}'),
('hsk1_c02_e02','hsk1_c02',2,'reorder','["我","学生","是"]',NULL,'Put the words in the correct order.','{"tokens":["我","是","学生"]}',NULL,'[]','Basic noun-predicate identity: 我是学生。','["我", "是", "学生"]','["word_order"]',1,10,'{}'),
('hsk1_c02_e03','hsk1_c02',3,'translate_to_zh','My name is Li Ming.',NULL,'Translate into Chinese.','{"value":"我叫李明。"}',NULL,'["我叫李明","我叫李明。"]','Use 我叫 + name.','["我", "叫"]','["self_intro"]',2,10,'{}'),
('hsk1_c02_e04','hsk1_c02',4,'dialogue_choice','A: 你叫什么名字？ B: ____',NULL,'Choose the best answer.','{"value":"我叫王明。"}','["我叫王明。","我是很好。","你叫王明。","再见。"]','[]','Answer a name question with 我叫 + name.','["我", "叫"]','["dialogue"]',1,10,'{}'),
('hsk1_c03_e01','hsk1_c03',1,'fill_blank','她____老师。',NULL,'Choose the missing word.','{"value":"是"}',NULL,'["是"]','Use 是 to link 她 and 老师.','["是"]','["copula"]',1,10,'{}'),
('hsk1_c03_e02','hsk1_c03',2,'reorder','["他","学生","是"]',NULL,'Put the words in order.','{"tokens":["他","是","学生"]}',NULL,'[]','The order is subject + 是 + noun.','["他", "是", "学生"]','["word_order"]',1,10,'{}'),
('hsk1_c03_e03','hsk1_c03',3,'en_to_zh_mcq','She is a student.',NULL,'Choose the correct Chinese sentence.','{"value":"她是学生。"}','["她是学生。","她学生是。","是她学生。","她很学生。"]','[]','Use 她 + 是 + 学生.','["她", "是", "学生"]','["copula", "word_order"]',1,10,'{}'),
('hsk1_c03_e04','hsk1_c03',4,'translate_to_zh','I am a teacher.',NULL,'Translate into Chinese.','{"value":"我是老师。"}',NULL,'["我是老师","我是老师。"]','Use 我是老师。','["我", "是", "老师"]','["copula"]',2,10,'{}'),
('hsk1_c04_e01','hsk1_c04',1,'fill_blank','你是学生____？',NULL,'Make it a yes/no question.','{"value":"吗"}',NULL,'["吗"]','Add 吗 at the end of a statement.','["吗"]','["target_ma"]',1,10,'{}'),
('hsk1_c04_e02','hsk1_c04',2,'reorder','["吗","你","老师","是"]',NULL,'Put the words in order.','{"tokens":["你","是","老师","吗"]}',NULL,'[]','吗 goes at the end.','["吗"]','["target_ma", "word_order"]',1,10,'{}'),
('hsk1_c04_e03','hsk1_c04',3,'en_to_zh_mcq','Are you a student?',NULL,'Choose the sentence that specifically uses 吗.','{"value":"你是学生吗？"}','["你是学生吗？","你是不是学生？","你学生吗是？","吗你是学生？"]','[]','The target pattern is statement + 吗.','["吗"]','["target_ma"]',2,10,'{}'),
('hsk1_c04_e04','hsk1_c04',4,'translate_to_zh','Is she a teacher? Use 吗.',NULL,'Translate using the target grammar.','{"value":"她是老师吗？"}',NULL,'["她是老师吗","她是老师吗？"]','For this exercise, correct meaning alone is not enough; the target is 吗.','["吗", "她", "是", "老师"]','["target_ma", "target_concept_gate"]',2,10,'{}'),
('hsk1_c05_e01','hsk1_c05',1,'fill_blank','我是学生。你____？',NULL,'Complete “What about you?”','{"value":"呢"}',NULL,'["呢"]','Use 呢 to return the topic/question.','["呢"]','["target_ne"]',1,10,'{}'),
('hsk1_c05_e02','hsk1_c05',2,'dialogue_choice','A: 我很好。你呢？ B: ____',NULL,'Choose a natural answer.','{"value":"我也很好。"}','["我也很好。","你呢？","什么？","再见吗？"]','[]','Answer the returned topic naturally.','["呢"]','["dialogue"]',1,10,'{}'),
('hsk1_c05_e03','hsk1_c05',3,'reorder','["呢","他"]',NULL,'Make “What about him?”','{"tokens":["他","呢"]}',NULL,'[]','Pronoun + 呢 forms a short follow-up.','["呢"]','["word_order"]',1,10,'{}'),
('hsk1_c05_e04','hsk1_c05',4,'translate_to_zh','I am a teacher. What about you?',NULL,'Translate into Chinese.','{"value":"我是老师。你呢？"}',NULL,'["我是老师，你呢？","我是老师。你呢？","我是老师。你呢"]','Use 你呢？ for the follow-up.','["呢"]','["target_ne"]',2,10,'{}'),
('hsk1_c06_e01','hsk1_c06',1,'fill_blank','这____什么？',NULL,'Complete the question.','{"value":"是"}',NULL,'["是"]','这是什么？ means “What is this?”','["什么"]','["what_question"]',1,10,'{}'),
('hsk1_c06_e02','hsk1_c06',2,'reorder','["什么","是","这"]',NULL,'Put the words in order.','{"tokens":["这","是","什么"]}',NULL,'[]','Keep 什么 in the position of the unknown noun.','["什么"]','["word_order"]',1,10,'{}'),
('hsk1_c06_e03','hsk1_c06',3,'meaning_mcq','什么',NULL,'Choose the meaning.','{"value":"what"}','["what","who","where","which"]','[]','什么 means “what”.','["什么"]','["vocab_meaning"]',1,10,'{}'),
('hsk1_c06_e04','hsk1_c06',4,'translate_to_zh','What is this?',NULL,'Translate into Chinese.','{"value":"这是什么？"}',NULL,'["这是什么","这是什么？"]','Use 这 + 是 + 什么.','["什么"]','["what_question"]',2,10,'{}'),
('hsk1_c07_e01','hsk1_c07',1,'meaning_mcq','谁',NULL,'Choose the meaning.','{"value":"who"}','["who","what","where","how"]','[]','谁 asks about a person.','["谁"]','["vocab_meaning"]',1,10,'{}'),
('hsk1_c07_e02','hsk1_c07',2,'reorder','["谁","她","是"]',NULL,'Put the words in order.','{"tokens":["她","是","谁"]}',NULL,'[]','谁 occupies the unknown person position.','["谁"]','["word_order"]',1,10,'{}'),
('hsk1_c07_e03','hsk1_c07',3,'dialogue_choice','A: 他是谁？ B: ____',NULL,'Choose the best answer.','{"value":"他是我的老师。"}','["他是我的老师。","他在哪儿？","什么老师？","我是学生吗？"]','[]','A 谁 question expects a person identity.','["谁"]','["dialogue"]',1,10,'{}'),
('hsk1_c07_e04','hsk1_c07',4,'translate_to_zh','Who is she?',NULL,'Translate into Chinese.','{"value":"她是谁？"}',NULL,'["她是谁","她是谁？"]','Use 她 + 是 + 谁.','["谁"]','["who_question"]',2,10,'{}'),
('hsk1_c08_e01','hsk1_c08',1,'meaning_mcq','哪儿',NULL,'Choose the meaning.','{"value":"where"}','["where","who","what","when"]','[]','哪儿 means “where”.','["哪儿"]','["vocab_meaning"]',1,10,'{}'),
('hsk1_c08_e02','hsk1_c08',2,'reorder','["哪儿","你","在"]',NULL,'Put the words in order.','{"tokens":["你","在","哪儿"]}',NULL,'[]','The basic location question is 你在哪儿？','["哪儿", "在"]','["word_order", "location"]',1,10,'{}'),
('hsk1_c08_e03','hsk1_c08',3,'fill_blank','你在____？',NULL,'Complete: “Where are you?”','{"value":"哪儿"}',NULL,'["哪儿","哪里"]','哪儿/哪里 can ask location; this module teaches 哪儿.','["哪儿"]','["where_question"]',1,10,'{}'),
('hsk1_c08_e04','hsk1_c08',4,'en_to_zh_mcq','Which book?',NULL,'Choose the best phrase.','{"value":"哪本书？"}','["哪本书？","哪儿书？","谁本书？","什么在书？"]','[]','哪 combines with a classifier before a noun.','["哪"]','["which_question", "classifier"]',2,10,'{}'),
('hsk1_c09_e01','hsk1_c09',1,'meaning_mcq','这 / 那',NULL,'Choose the best meaning pair.','{"value":"this / that"}','["this / that","who / what","here / where","I / you"]','[]','这 = this; 那 = that.','["这", "那"]','["demonstrative"]',1,10,'{}'),
('hsk1_c09_e02','hsk1_c09',2,'fill_blank','____是我的书。（near me）',NULL,'Choose “this”.','{"value":"这"}',NULL,'["这"]','Use 这 for something near the speaker.','["这"]','["demonstrative"]',1,10,'{}'),
('hsk1_c09_e03','hsk1_c09',3,'reorder','["个","那","学生"]',NULL,'Put the phrase in order.','{"tokens":["那","个","学生"]}',NULL,'[]','Demonstrative + classifier + noun.','["那", "个"]','["word_order", "classifier"]',1,10,'{}'),
('hsk1_c09_e04','hsk1_c09',4,'translate_to_zh','That is my teacher.',NULL,'Translate into Chinese.','{"value":"那是我的老师。"}',NULL,'["那是我的老师","那是我的老师。"]','Use 那 for “that”.','["那"]','["demonstrative"]',2,10,'{}'),
('hsk1_c10_e01','hsk1_c10',1,'fill_blank','我____一本书。',NULL,'Complete: “I have a book.”','{"value":"有"}',NULL,'["有"]','Use 有 for possession.','["有"]','["possession"]',1,10,'{}'),
('hsk1_c10_e02','hsk1_c10',2,'en_to_zh_mcq','I do not have money.',NULL,'Choose the correct sentence.','{"value":"我没有钱。"}','["我没有钱。","我不有钱。","我有不钱。","没有我钱。"]','[]','有 is negated with 没有.','["没有"]','["negation_you"]',1,10,'{}'),
('hsk1_c10_e03','hsk1_c10',3,'reorder','["朋友","有","我"]',NULL,'Put the words in order.','{"tokens":["我","有","朋友"]}',NULL,'[]','Subject + 有 + object.','["有"]','["word_order"]',1,10,'{}'),
('hsk1_c10_e04','hsk1_c10',4,'translate_to_zh','She does not have a book.',NULL,'Translate into Chinese.','{"value":"她没有书。"}',NULL,'["她没有书","她没有书。"]','Use 没有, not 不有.','["没有"]','["negation_you"]',2,10,'{}'),
('hsk1_c11_e01','hsk1_c11',1,'fill_blank','我____喝茶。',NULL,'Complete: “I do not drink tea.”','{"value":"不"}',NULL,'["不"]','Use 不 before the verb 喝.','["不"]','["negation_bu"]',1,10,'{}'),
('hsk1_c11_e02','hsk1_c11',2,'reorder','["不","我","学生","是"]',NULL,'Put the words in order.','{"tokens":["我","不","是","学生"]}',NULL,'[]','不 comes before 是.','["不"]','["word_order", "negation_bu"]',1,10,'{}'),
('hsk1_c11_e03','hsk1_c11',3,'en_to_zh_mcq','I do not like coffee.',NULL,'Choose the correct structure.','{"value":"我不喜欢咖啡。"}','["我不喜欢咖啡。","我喜欢不咖啡。","不我喜欢咖啡。","我没有喜欢咖啡。"]','[]','Use 不 before 喜欢 for a general preference.','["不"]','["negation_bu"]',2,10,'{}'),
('hsk1_c11_e04','hsk1_c11',4,'translate_to_zh','I will not go tomorrow.',NULL,'Translate into Chinese.','{"value":"我明天不去。"}',NULL,'["我明天不去","我明天不去。","明天我不去。","明天我不去"]','Use 不 for a future intention.','["不"]','["negation_bu"]',2,10,'{}'),
('hsk1_c12_e01','hsk1_c12',1,'fill_blank','我____书',NULL,'Complete: “my book”.','{"value":"的"}',NULL,'["的"]','A 的 B marks possession/modification.','["的"]','["de_possession"]',1,10,'{}'),
('hsk1_c12_e02','hsk1_c12',2,'reorder','["老师","的","我"]',NULL,'Make “my teacher”.','{"tokens":["我","的","老师"]}',NULL,'[]','Possessor + 的 + noun.','["的"]','["word_order", "de_possession"]',1,10,'{}'),
('hsk1_c12_e03','hsk1_c12',3,'en_to_zh_mcq','her friend',NULL,'Choose the correct phrase.','{"value":"她的朋友"}','["她的朋友","她朋友的","的她朋友","她是朋友"]','[]','Use 她的 + noun.','["的"]','["de_possession"]',1,10,'{}'),
('hsk1_c12_e04','hsk1_c12',4,'translate_to_zh','This is my book.',NULL,'Translate into Chinese.','{"value":"这是我的书。"}',NULL,'["这是我的书","这是我的书。"]','我的 modifies 书.','["的"]','["de_possession"]',2,10,'{}'),
('hsk1_c13_e01','hsk1_c13',1,'fill_blank','天气____好。',NULL,'Complete the natural beginner sentence.','{"value":"很"}',NULL,'["很"]','很 commonly links the subject and adjective predicate.','["很"]','["adjective_predicate"]',1,10,'{}'),
('hsk1_c13_e02','hsk1_c13',2,'reorder','["很","她","高兴"]',NULL,'Put the words in order.','{"tokens":["她","很","高兴"]}',NULL,'[]','Subject + 很 + adjective.','["很"]','["word_order", "adjective_predicate"]',1,10,'{}'),
('hsk1_c13_e03','hsk1_c13',3,'en_to_zh_mcq','The school is big.',NULL,'Choose the beginner pattern.','{"value":"学校很大。"}','["学校很大。","学校是大。","很学校大。","学校大很。"]','[]','Adjective predicates normally do not use 是 here.','["很"]','["shi_overuse", "adjective_predicate"]',2,10,'{}'),
('hsk1_c13_e04','hsk1_c13',4,'translate_to_zh','She is very happy.',NULL,'Translate into Chinese.','{"value":"她很高兴。"}',NULL,'["她很高兴","她很高兴。"]','Use 她很高兴。','["很"]','["adjective_predicate"]',2,10,'{}'),
('hsk1_c14_e01','hsk1_c14',1,'fill_blank','我是学生，她____是学生。',NULL,'Complete: “She is also a student.”','{"value":"也"}',NULL,'["也"]','也 appears before 是.','["也"]','["ye_word_order"]',1,10,'{}'),
('hsk1_c14_e02','hsk1_c14',2,'fill_blank','我们____是学生。',NULL,'Complete: “We are all students.”','{"value":"都"}',NULL,'["都"]','都 marks the group as all/both.','["都"]','["dou_word_order"]',1,10,'{}'),
('hsk1_c14_e03','hsk1_c14',3,'reorder','["也","我","喜欢","茶"]',NULL,'Put the words in order.','{"tokens":["我","也","喜欢","茶"]}',NULL,'[]','也 normally comes after the subject and before the predicate.','["也"]','["word_order"]',2,10,'{}'),
('hsk1_c14_e04','hsk1_c14',4,'translate_to_zh','They are all teachers.',NULL,'Translate into Chinese.','{"value":"他们都是老师。"}',NULL,'["他们都是老师","他们都是老师。"]','Use 他们 + 都 + 是 + 老师.','["都"]','["dou_word_order"]',2,10,'{}'),
('hsk1_c15_e01','hsk1_c15',1,'meaning_mcq','八',NULL,'Choose the number.','{"value":"8"}','["6","7","8","9"]','[]','八 = 8.','["八"]','["number"]',1,10,'{}'),
('hsk1_c15_e02','hsk1_c15',2,'en_to_zh_mcq','three',NULL,'Choose the Chinese number.','{"value":"三"}','["二","三","五","十"]','[]','三 = three.','["三"]','["number"]',1,10,'{}'),
('hsk1_c15_e03','hsk1_c15',3,'fill_blank','九 + 一 = ____',NULL,'Answer in Chinese.','{"value":"十"}',NULL,'["十"]','九加一等于十.','["十"]','["number"]',1,10,'{}'),
('hsk1_c15_e04','hsk1_c15',4,'reorder','["个","三","人"]',NULL,'Make “three people”.','{"tokens":["三","个","人"]}',NULL,'[]','Number + classifier + noun.','["三", "个"]','["number", "classifier"]',2,10,'{}'),
('hsk1_c16_e01','hsk1_c16',1,'fill_blank','你有____个朋友？',NULL,'Ask “how many friends?”','{"value":"几"}',NULL,'["几"]','几 is natural for a small expected count.','["几"]','["quantity_question"]',1,10,'{}'),
('hsk1_c16_e02','hsk1_c16',2,'meaning_mcq','多少',NULL,'Choose the meaning.','{"value":"how many / how much"}','["how many / how much","who","where","this"]','[]','多少 asks quantity/amount.','["多少"]','["quantity_question"]',1,10,'{}'),
('hsk1_c16_e03','hsk1_c16',3,'reorder','["钱","多少","这","？"]',NULL,'Make “How much is this?” using the given tokens.','{"tokens":["这","多少","钱","？"]}',NULL,'[]','A beginner price question can be 这多少钱？','["多少", "钱"]','["word_order", "quantity_question"]',2,10,'{}'),
('hsk1_c16_e04','hsk1_c16',4,'dialogue_choice','A: 你有几个学生？ B: ____',NULL,'Choose the best answer.','{"value":"我有三个学生。"}','["我有三个学生。","我是学生吗？","学生在哪儿？","我很好。"]','[]','A 几 question expects a number response.','["几", "个"]','["dialogue", "quantity_question"]',1,10,'{}'),
('hsk1_c17_e01','hsk1_c17',1,'fill_blank','三____学生',NULL,'Add the classifier.','{"value":"个"}',NULL,'["个"]','Use 个 between the number and 学生.','["个"]','["classifier"]',1,10,'{}'),
('hsk1_c17_e02','hsk1_c17',2,'reorder','["人","个","一"]',NULL,'Make “one person”.','{"tokens":["一","个","人"]}',NULL,'[]','Number + 个 + noun.','["个"]','["word_order", "classifier"]',1,10,'{}'),
('hsk1_c17_e03','hsk1_c17',3,'en_to_zh_mcq','this student',NULL,'Choose the correct phrase.','{"value":"这个学生"}','["这个学生","这学生个","个这学生","学生这个"]','[]','Demonstrative + 个 + noun.','["个", "这"]','["classifier"]',1,10,'{}'),
('hsk1_c17_e04','hsk1_c17',4,'translate_to_zh','three students',NULL,'Translate into Chinese.','{"value":"三个学生"}',NULL,'["三个学生"]','Use 三 + 个 + 学生.','["个"]','["classifier"]',2,10,'{}'),
('hsk1_c18_e01','hsk1_c18',1,'fill_blank','我____学校。',NULL,'Complete: “I am at school.”','{"value":"在"}',NULL,'["在"]','在 introduces the location.','["在"]','["location"]',1,10,'{}'),
('hsk1_c18_e02','hsk1_c18',2,'reorder','["家","他","在"]',NULL,'Put the words in order.','{"tokens":["他","在","家"]}',NULL,'[]','Subject + 在 + place.','["在"]','["word_order", "location"]',1,10,'{}'),
('hsk1_c18_e03','hsk1_c18',3,'en_to_zh_mcq','She is at the hospital.',NULL,'Choose the correct sentence.','{"value":"她在医院。"}','["她在医院。","她医院在。","在她医院。","她是医院。"]','[]','Use 她 + 在 + 医院.','["在"]','["location"]',1,10,'{}'),
('hsk1_c18_e04','hsk1_c18',4,'translate_to_zh','I am in China.',NULL,'Translate into Chinese.','{"value":"我在中国。"}',NULL,'["我在中国","我在中国。"]','Use 在 before 中国.','["在"]','["location"]',2,10,'{}'),
('hsk1_c19_e01','hsk1_c19',1,'meaning_mcq','明天',NULL,'Choose the meaning.','{"value":"tomorrow"}','["today","tomorrow","yesterday","morning"]','[]','明天 = tomorrow.','["明天"]','["time"]',1,10,'{}'),
('hsk1_c19_e02','hsk1_c19',2,'reorder','["去","我","明天","学校"]',NULL,'Put the words in a natural order.','{"tokens":["我","明天","去","学校"]}',NULL,'[]','A common order is subject + time + verb + place/object.','["明天"]','["word_order", "time"]',2,10,'{}'),
('hsk1_c19_e03','hsk1_c19',3,'fill_blank','现在三____。',NULL,'Complete: “It is 3 o’clock now.”','{"value":"点"}',NULL,'["点"]','Use 点 after the hour number.','["点"]','["clock_time"]',1,10,'{}'),
('hsk1_c19_e04','hsk1_c19',4,'translate_to_zh','I will go to school tomorrow.',NULL,'Translate into Chinese.','{"value":"我明天去学校。"}',NULL,'["我明天去学校","我明天去学校。","明天我去学校。","明天我去学校"]','Both common time placements are accepted.','["明天"]','["time"]',2,10,'{}'),
('hsk1_c20_e01','hsk1_c20',1,'fill_blank','我____喝茶。（like）',NULL,'Complete using “like”.','{"value":"喜欢"}',NULL,'["喜欢"]','喜欢 expresses preference.','["喜欢"]','["preference"]',1,10,'{}'),
('hsk1_c20_e02','hsk1_c20',2,'fill_blank','我____学汉语。（want）',NULL,'Complete using “want”.','{"value":"想"}',NULL,'["想"]','想 + verb expresses intention/desire.','["想"]','["intention"]',1,10,'{}'),
('hsk1_c20_e03','hsk1_c20',3,'dialogue_choice','A: 你会说汉语吗？ B: ____',NULL,'Choose the best answer.','{"value":"我会说一点儿。"}','["我会说一点儿。","我是汉语。","我在汉语。","我有说。"]','[]','会 + verb expresses learned ability.','["会"]','["ability", "dialogue"]',2,10,'{}'),
('hsk1_c20_e04','hsk1_c20',4,'translate_to_zh','I want to learn Chinese.',NULL,'Translate into Chinese.','{"value":"我想学汉语。"}',NULL,'["我想学汉语","我想学汉语。","我想学习汉语。","我想学习汉语"]','Use 想 + 学/学习 + 汉语.','["想"]','["intention"]',2,10,'{}'),
('hsk6_c13_e01_3','hsk6_c13',1,'zh_to_en_mcq','千年雪莲','qiānnián xuělián','Select the correct English translation.','{"value": "thousand year snow lotus"}','["thousand year snow lotus", "Of course I want to go see a movie.", "The store is the the left of the school.", "after three hundred years of incubation, the vermilion bird finally hatched from the nest"]','["thousand year snow lotus"]','千年雪莲 (qiānnián xuělián) means: “thousand year snow lotus”','["千年雪莲"]','["reading_comprehension"]',5,10,'{"source": "example.db", "unit": 89, "sentence_id": 3}'),
('hsk4_c15_e01_99','hsk4_c15',1,'zh_to_en_mcq','如果你打算参加聚会，请报名','rúguǒ nǐ dǎsuàn cānjiā jùhuì, qǐng bàomíng','Select the correct English translation.','{"value": "if you plan to attend the party, please register"}','["she likes wearing hats", "I am a student.", "if you plan to attend the party, please register", "I like the white one the most"]','["if you plan to attend the party, please register"]','如果你打算参加聚会，请报名 (rúguǒ nǐ dǎsuàn cānjiā jùhuì, qǐng bàomíng) means: “if you plan to attend the party, please register”','["如果你打算参加聚会，请报名"]','["reading_comprehension"]',4,10,'{"source": "example.db", "unit": 61, "sentence_id": 99}'),
('hsk4_c14_e01_100','hsk4_c14',1,'zh_to_en_mcq','我保证我会按时完成工作','wǒ bǎozhèng wǒ huì ànshí wánchéng gōngzuò','Select the correct English translation.','{"value": "I guarantee that I will finish the work on time"}','["I guarantee that I will finish the work on time", "There is an exam today.", "happy birthday!", "our meeting is taking place in the school library"]','["I guarantee that I will finish the work on time"]','我保证我会按时完成工作 (wǒ bǎozhèng wǒ huì ànshí wánchéng gōngzuò) means: “I guarantee that I will finish the work on time”','["我保证我会按时完成工作"]','["reading_comprehension"]',4,10,'{"source": "example.db", "unit": 60, "sentence_id": 100}'),
('hsk4_c18_e01_101','hsk4_c18',1,'zh_to_en_mcq','我已经看了这个电影三遍，我不想重新看','wo yǐjīng kànle zhège diànyǐng sān biàn, wǒ bùxiǎng chóngxīn kàn','Select the correct English translation.','{"value": "I’ve already seen this movie three times, I don’t want to watch it again"}','["please print the article", "I’ve already seen this movie three times, I don’t want to watch it again", "If he doesn''t show up by nine o''clock, we will leave.", "This year''s Spring Festival is on January 28th."]','["I’ve already seen this movie three times, I don’t want to watch it again"]','我已经看了这个电影三遍，我不想重新看 (wo yǐjīng kànle zhège diànyǐng sān biàn, wǒ bùxiǎng chóngxīn kàn) means: “I’ve already seen this movie three times, I don’t want to watch it again”','["我已经看了这个电影三遍，我不想重新看"]','["reading_comprehension"]',4,10,'{"source": "example.db", "unit": 66, "sentence_id": 101}'),
('hsk4_c09_e01_103','hsk4_c09',1,'zh_to_en_mcq','他一直坚持节约钱，终于积累了够的钱买新手机','tā yīzhí jiānchí jiéyuē qián, zhōngyú jīlěile gòu de qián mǎi xīn shǒujī','Select the correct English translation.','{"value": "he has always insisted on saving money and finally accumulated enough to buy a new smartphone."}','["Do you have any other questions?", "he has always insisted on saving money and finally accumulated enough to buy a new smartphone.", "I can help you.", "I''d like a cup of beer."]','["he has always insisted on saving money and finally accumulated enough to buy a new smartphone."]','他一直坚持节约钱，终于积累了够的钱买新手机 (tā yīzhí jiānchí jiéyuē qián, zhōngyú jīlěile gòu de qián mǎi xīn shǒujī) means: “he has always insisted on saving money and finally accumulated enough to buy a new smartphone.”','["他一直坚持节约钱，终于积累了够的钱买新手机"]','["reading_comprehension"]',4,10,'{"source": "example.db", "unit": 55, "sentence_id": 103}'),
('hsk4_c17_e01_104','hsk4_c17',1,'zh_to_en_mcq','由于一次吵，他们的友谊断了','yóuyú yīcì chǎo, tāmen de yǒuyì duànle','Select the correct English translation.','{"value": "due to a quarrel, their friendship ended."}','["due to a quarrel, their friendship ended.", "the responsibility of the police is to protect people from danger", "The manager was angry because I was late.", "please tell me the last four digits of your phone number"]','["due to a quarrel, their friendship ended."]','由于一次吵，他们的友谊断了 (yóuyú yīcì chǎo, tāmen de yǒuyì duànle) means: “due to a quarrel, their friendship ended.”','["由于一次吵，他们的友谊断了"]','["reading_comprehension"]',4,10,'{"source": "example.db", "unit": 63, "sentence_id": 104}'),
('hsk4_c31_e01_105','hsk4_c31',1,'zh_to_en_mcq','不管天气好坏，即使下雨，他每天都去跑步。','Bùguǎn tiānqì hǎo huài, jíshǐ xià yǔ, tā měitiān dōu qù pǎobù','Select the correct English translation.','{"value": "Regardless of good or bad weather, even if it’s raining, he goes running every day"}','["Who are you?", "His mother made us a cake.", "I got to work late yesterday.", "Regardless of good or bad weather, even if it’s raining, he goes running every day"]','["Regardless of good or bad weather, even if it’s raining, he goes running every day"]','不管天气好坏，即使下雨，他每天都去跑步。 (Bùguǎn tiānqì hǎo huài, jíshǐ xià yǔ, tā měitiān dōu qù pǎobù) means: “Regardless of good or bad weather, even if it’s raining, he goes running every day”','["不管天气好坏，即使下雨，他每天都去跑步。"]','["reading_comprehension"]',4,10,'{"source": "example.db", "unit": 93, "sentence_id": 105}'),
('hsk4_c19_e01_106','hsk4_c19',1,'zh_to_en_mcq','请你详细地说明这个问题','qǐng nǐ xiángxì de shuōmíng zhège wèntí','Select the correct English translation.','{"value": "please explain this issue in detail"}','["What time do you wake up every day?", "He works out really hard.", "please explain this issue in detail", "despite being tired, he actively gave up his seat on the bus for an elderly person"]','["please explain this issue in detail"]','请你详细地说明这个问题 (qǐng nǐ xiángxì de shuōmíng zhège wèntí) means: “please explain this issue in detail”','["请你详细地说明这个问题"]','["reading_comprehension"]',4,10,'{"source": "example.db", "unit": 70, "sentence_id": 106}'),
